import type { FoundationLessonDay } from './foundation-days'

export type Mascot = 'penguin' | 'panda' | 'pero'

export type Quiz = {
  context?: string
  question: string
  options: string[]
  correct: number
  feedback: string
}

export type RuleBlock = {
  title: string
  mascot: Mascot
  lead: string
  body: Array<string | { speaker: Mascot; text: string } | { table: { headers: string[]; rows: string[][] } }>
  examples: string[]
  /** Скороговорка: played back slowly, then normally, then fast. */
  tongueTwister?: {
    ru: string
    uz: string
    breakdown?: Array<{ word: string; transcription: string; sound: string }>
  }
}

export type Phrase = {
  ru: string
  uz: string
  pronunciation?: string
  example: string
  icon: string
}

export type Vocab = {
  ru: string
  uz: string
  example: string
  icon: string
}

export type LessonData = {
  day: number
  titleRu: string
  titleUz: string
  tests: Quiz[]
  phonetics: RuleBlock
  grammar: RuleBlock
  phrases: Phrase[]
  game: {
    kind?: 'matching' | 'gender-houses' | 'family-crossword' | 'plural-puzzle' | 'room-builder' | 'missing-bag' | 'city-map' | 'picture-description'
    title: string
    instruction: string
    pairs: Array<{ left: string; right: string }>
    clues?: Array<{ clue: string; answer: string }>
    example?: string
    feedback?: { correct: string; incorrect: string; allDone: string }
  }
  dialogue: string[]
  questions: Array<{ question: string; answer: string }>
  vocabulary: Vocab[]
  exercise: {
    title: string
    instruction: string
    starter: string
    example?: string
  }
  outcomes: Array<{ title: string; translation: string; tone: 'yellow' | 'blue' | 'red' }>
  sceneImage?: string
  completionMessage?: string
  completionAction?: { label: string; href: string }
  reflection?: { questions: Array<{ question: string; options: string[] }> }
}

const p = (ru: string, uz: string, icon: string, example = ru, pronunciation?: string): Phrase => ({
  ru: capitalizeFirstRussianLetter(ru),
  uz, icon, example, pronunciation,
})

const v = (ru: string, uz: string, icon: string, example: string): Vocab => ({ ru, uz, icon, example })

function capitalizeFirstRussianLetter(text: string) {
  return text.replace(/^([^А-ЯЁа-яё]*)([а-яё])/u, (_match, prefix: string, letter: string) => (
    `${prefix}${letter.toLocaleUpperCase('ru-RU')}`
  ))
}

